const characters=[{id:'roland',name:'Roland Banks',job:'A szövetségi ügynök',class:'Őrző',style:'',initial:'RB'},{id:'daisy',name:'Daisy Walker',job:'A könyvtáros',class:'Kutató',style:'seeker',initial:'DW'},{id:'agnes',name:'Agnes Baker',job:'A pincérnő',class:'Misztikus',style:'mystic',initial:'AB'},{id:'wendy',name:'Wendy Adams',job:'Az utcagyerek',class:'Túlélő',style:'survivor',initial:'WA'},{id:'skids',name:'“Skids” O’Toole',job:'A volt fegyenc',class:'Zsivány',style:'rogue',initial:'SO'}];
const initial=()=>({user:'anna',owner:'anna',session:{number:2,title:'The Midnight Masks',gm:'bence',closed:false,result:'',note:''},players:[{id:'anna',name:'Anna',char:'daisy',earned:5,spent:2,physical:0,mental:0,status:'',notes:'',deck:'',saved:false},{id:'bence',name:'Bence',char:'roland',earned:5,spent:3,physical:1,mental:0,status:'',notes:'',deck:'',saved:false},{id:'lili',name:'Lili',char:'agnes',earned:5,spent:2,physical:0,mental:1,status:'',notes:'',deck:'',saved:false}],history:[{title:'The Gathering',text:'A csapat lezárta az első alkalmat. Minden nyomozó 5 XP-t kapott.',by:'Bence',date:'2026. szeptember 6.',gm:'Anna'}],notes:[{text:'A ház leégett. Lita velünk tart.',by:'Anna',date:'1. alkalom'}]});
let state=initial(),view='overview',detailId=null;const key='arkham-prototype-v1';try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&saved.players?.length===3&&saved.session&&saved.history&&saved.notes)state=saved}catch{}
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),me=()=>state.players.find(p=>p.id===state.user),char=p=>characters.find(c=>c.id===p.char),gm=()=>state.user===state.session.gm,avatar=c=>`<div class="avatar ${c.style}" aria-hidden="true">${c.initial}</div>`;
function save(){try{localStorage.setItem(key,JSON.stringify(state));return true}catch{toast('A böngésző nem engedte a mentést. A változás csak a lap bezárásáig marad meg.');return false}}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}function record(title,text){state.history.unshift({title,text,by:me().name,date:new Date().toLocaleDateString('hu-HU'),gm:state.players.find(p=>p.id===state.session.gm).name})}
function navigate(v,id){view=v;detailId=id||null;render();window.scrollTo(0,0)}
function render(){const p=me();$('#app').innerHTML=`<div class="shell"><aside><div class="brand"><span class="brand-mark">◇</span>ARKHAM</div><div class="brand-sub">Kampánynapló</div><nav class="nav" aria-label="Főmenü">${[['overview','◈','Kampány'],['investigator','♧','Saját nyomozó'],['session','◇','Játékalkalom'],['journal','▤','Közös napló'],['history','◷','Előzmények']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span class="nav-icon">${i}</span>${t}</button>`).join('')}</nav><div class="aside-bottom"><span class="eyebrow">A társaság</span><p><strong>Vasárnapi nyomozók</strong><br>3 játékos · Meghívásos kampány</p><span>Kampánygazda: Anna</span></div></aside><main><header class="topbar"><span>Vasárnapi nyomozók <span style="margin:0 12px">/</span> The Night of the Zealot</span><div class="profile"><span class="demo-tag">PROTOTÍPUS</span><label for="user" style="margin:0" class="muted">Nézet:</label><select id="user" aria-label="Mintajátékos váltása">${state.players.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${x.name}${x.id===state.session.gm?' · Játékmester':''}</option>`).join('')}</select></div></header><div class="content">${view==='overview'?overview():view==='investigator'?investigator():view==='session'?sessionView():view==='journal'?journal():historyView()}<p class="footer-note">Kipróbálható minta · A módosítások ebben a böngészőben maradnak. A játékosváltó a szerepköröket szemlélteti; valódi belépés és közös szinkronizálás még nincs.</p></div></main></div>`;bind()}
function heading(k,t,sub,action=''){return `<div class="eyebrow">${k}</div><div class="heading"><div><h1>${t}</h1><p class="muted">${sub}</p></div>${action}</div>`}
function overview(){const s=state.session,p=me();return heading('A történet folytatódik','The Night of the Zealot','Kampánynapló · Normál nehézség')+`<section class="campaign"><div><span class="pill ${s.closed?'':'gold'}">${s.closed?'LEZÁRT ALKALOM':'AKTUÁLIS JÁTÉKALKALOM'}</span><h2>${esc(s.title)}</h2><p class="muted">${s.closed?'Az eredmények a naplóba kerültek.':'Rögzítsétek a nyomozók állapotát, mielőtt folytatódik a történet.'}</p><div class="meta"><span>${s.number}. alkalom</span><span>Játékmester: <strong>${state.players.find(x=>x.id===s.gm).name}</strong></span><span>${state.players.filter(x=>x.saved).length}/3 nyomozó adatai rögzítve</span></div></div><div class="actions"><button class="primary" data-nav="session">${s.closed?'Eredmények megtekintése':'Alkalom lezárása'} ↗</button></div></section><div class="stats"><div class="stat"><strong>${state.players.length}</strong><span>aktív nyomozó</span></div><div class="stat"><strong>${p.earned-p.spent}</strong><span>saját elkölthető XP</span></div><div class="stat"><strong>${s.number-1+(s.closed?1:0)}</strong><span>lezárt alkalom</span></div></div><div class="columns"><section><div class="section-title"><h2>A nyomozócsapat</h2><span class="muted" style="font-size:14px">3 / 4 hely</span></div><div class="investigators">${state.players.map(x=>{const c=char(x);return `<article class="person ${x.id===p.id?'mine':''}">${avatar(c)}<div class="person-info"><h3>${c.name} ${x.id===p.id?'<span class="pill gold">TE</span>':''}</h3><small>${x.name} · ${c.class}${x.id===s.gm?' · Játékmester':''}</small></div><div class="xp">${x.earned-x.spent}<small>XP maradt</small></div><button class="small ghost" data-person="${x.id}" aria-label="${c.name} adatlapja">↗</button></article>`}).join('')}</div></section><section><div class="section-title"><h2>A napló margóján</h2><button class="small ghost" data-nav="journal">Napló ↗</button></div><div class="panel"><span class="eyebrow">Legutóbbi közös bejegyzés</span><p class="note">${esc(state.notes.at(-1)?.text||'Még nincs bejegyzés.')}</p><div class="timeline-item"><small>1. ALKALOM · LEZÁRVA</small><h3 style="margin-top:8px">The Gathering</h3><p>A történet elkezdődött.</p></div><span class="muted" style="font-size:14px">A közös döntéseket az alkalom játékmestere vezeti.</span></div></section></div>`}
function investigator(){const p=state.players.find(x=>x.id===detailId)||me(),c=char(p),own=p.id===state.user;return heading('Nyomozói dosszié',own?'Saját nyomozó':`${p.name} nyomozója`,own?'Minden változás ehhez a kampányhoz tartozik.':'A csapattársak adatlapja megtekinthető, de nem szerkeszthető.')+`<div class="columns"><section class="panel"><div class="detail-head">${avatar(c)}<div><span class="eyebrow">${c.class}</span><h2>${c.name}</h2><span class="muted">${c.job}</span></div></div>${own?'<button id="choose" class="small ghost" style="margin-bottom:24px">Karakter kiválasztása / cseréje</button>':''}<form id="investigator-form"><fieldset style="border:0;padding:0;margin:0" ${own?'':'disabled'}><div class="form-grid"><div class="field"><label>Összes megszerzett XP</label><input value="${p.earned}" disabled></div><div class="field"><label for="spent">Összes elköltött XP</label><input id="spent" name="spent" type="number" min="0" max="${p.earned}" value="${p.spent}" required></div><div class="field"><label for="physical">Fizikai trauma</label><input id="physical" name="physical" type="number" min="0" max="99" value="${p.physical}" required></div><div class="field"><label for="mental">Mentális trauma</label><input id="mental" name="mental" type="number" min="0" max="99" value="${p.mental}" required></div><div class="field full"><label for="status">Állapotok</label><input id="status" name="status" placeholder="Például: sérülés, átok, történeti állapot…" value="${esc(p.status)}"></div><div class="field full"><label for="deck">Pakli linkje</label><input id="deck" name="deck" type="url" placeholder="https://…" value="${esc(p.deck)}"></div><div class="field full"><label for="notes">Saját jegyzetek</label><textarea id="notes" name="notes">${esc(p.notes)}</textarea></div></div>${own?'<button class="primary" type="submit">Változások mentése</button>':''}</fieldset></form></section><section><div class="panel"><span class="eyebrow">Fejlődés</span><div class="stat" style="padding-left:0"><strong>${p.earned-p.spent}</strong><span>elkölthető XP</span></div><p class="muted">${p.earned} XP megszerezve · ${p.spent} XP elköltve</p><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>Az alkalom jutalma</h3><p class="muted">A most kapott XP-t az alkalom lezárásánál add meg. Így megmarad, mikor és mennyit szereztél.</p><button data-nav="session" class="ghost">Ugrás az alkalomhoz ↗</button></div></section></div>`}
function sessionView(){const s=state.session,p=me(),all=state.players.every(x=>x.saved);return heading(`${s.number}. játékalkalom`,esc(s.title),s.closed?'Az alkalom lezárva. Az eredmények megmaradtak a naplóban.':'Saját eredmények és közös történet, egy helyen.',`<span class="pill ${s.closed?'':'gold'}">${s.closed?'LEZÁRVA':'RÖGZÍTÉS ALATT'}</span>`)+`<div class="columns"><section><div class="panel"><div class="section-title"><h2>Saját eredményeim</h2><span class="pill ${p.saved?'':'gold'}">${p.saved?'Rögzítve':'Kitöltésre vár'}</span></div><p class="muted">${char(p).name} · ${p.name}</p>${p.saved?`<div class="review"><strong>Az eredményeidet elmentetted.</strong><p>Kapott XP: ${p.sessionResult?.xp??0} · Fizikai trauma: +${p.sessionResult?.physical??0} · Mentális trauma: +${p.sessionResult?.mental??0}</p></div><button data-nav="investigator" class="ghost">Nyomozó adatlapja ↗</button>`:s.closed?'<p>Az alkalom már lezárult.</p>':`<form id="result-form"><div class="form-grid"><div class="field full"><label for="xp">Az alkalom során kapott XP</label><input id="xp" name="xp" type="number" min="0" max="99" value="0" required></div><div class="field"><label for="addphysical">Új fizikai trauma</label><input id="addphysical" name="physical" type="number" min="0" max="99" value="0" required></div><div class="field"><label for="addmental">Új mentális trauma</label><input id="addmental" name="mental" type="number" min="0" max="99" value="0" required></div><div class="field full"><label for="newstatus">Új állapot / személyes megjegyzés</label><textarea id="newstatus" name="note" placeholder="Mi változott a nyomozódnál?"></textarea></div></div><button type="submit" class="primary">Eredmények áttekintése</button></form>`}</div><div class="panel" style="margin-top:20px"><h2>Közös eredmény</h2>${gm()?`<form id="common-form"><fieldset style="border:0;padding:0;margin:0" ${s.closed?'disabled':''}><div class="field"><label for="resolution">Végkifejlet / eredmény</label><input id="resolution" name="resolution" required placeholder="Például: R1 – a forgatókönyv szerinti eredmény" value="${esc(s.result)}"></div><div class="field"><label for="common-note">Közös döntések és változások</label><textarea id="common-note" name="note" placeholder="Mit kell megőrizni a következő alkalomra?">${esc(s.note)}</textarea></div>${s.closed?'':'<button class="ghost">Közös eredmény mentése</button>'}</fieldset></form>`:`<p>${esc(s.result||'A játékmester még nem rögzítette az eredményt.')}</p><p class="muted">${esc(s.note)}</p><span class="muted">Ezt a részt ${state.players.find(x=>x.id===s.gm).name}, az alkalom játékmestere szerkeszti.</span>`}</div></section><section><div class="panel"><h2>Az alkalom felelőse</h2><label for="gm">Játékmester</label><select id="gm" ${s.closed||!(gm()||state.user===state.owner)?'disabled':''}>${state.players.map(x=>`<option value="${x.id}" ${x.id===s.gm?'selected':''}>${x.name}</option>`).join('')}</select><p class="muted" style="font-size:14px;margin-top:12px">Az aktuális játékmester és a kampánygazda átadhatja a szerepet.</p><h3 style="margin-top:28px">Csapat visszajelzései</h3><ul class="checklist">${state.players.map(x=>`<li><span>${x.name}</span><span style="color:${x.saved?'var(--green)':'var(--muted)'}">${x.saved?'✓ Rögzítve':'Még hátravan'}</span></li>`).join('')}</ul>${s.closed?`<button id="next" class="primary" ${gm()||state.user===state.owner?'':'disabled'}>Következő alkalom</button>`:`<p class="muted" style="font-size:14px">Lezárható, ha mindenki mentett, és a közös eredmény is elkészült.</p><button id="close-session" class="primary" ${gm()&&all&&s.result?'':'disabled'}>Alkalom végleges lezárása</button>`}</div></section></div>`}
function journal(){return heading('Közös emlékezet','Kampánynapló','Döntések és következmények a következő alkalomhoz.')+`<div class="columns"><section class="history">${state.notes.map(n=>`<article class="panel"><span class="eyebrow">${esc(n.date)} · ${esc(n.by)}</span><p style="margin:14px 0 0;white-space:pre-wrap">${esc(n.text)}</p></article>`).join('')}</section><section class="panel" style="align-self:start"><h2>Új bejegyzés</h2>${gm()&&!state.session.closed?'<form id="note-form"><label for="journal-note">Mit jegyezzen meg a csapat?</label><textarea id="journal-note" name="note" required maxlength="5000"></textarea><button class="primary" style="margin-top:16px">Bejegyzés mentése</button></form>':`<p class="muted">${state.session.closed?'Új közös bejegyzést a következő alkalom indítása után rögzíthettek.':'A közös naplót az aktuális játékmester szerkeszti. A próba során a felső játékosváltóval léphetsz a nézetébe.'}</p>`}</section></div>`}
function historyView(){return heading('Visszakereshető történet','Előzmények','A kampány változásai, a legfrissebb bejegyzéssel kezdve.')+`<div class="history">${state.history.map(h=>`<article class="panel"><div class="eyebrow">${esc(h.date)} · ${esc(h.by)}</div><h3 style="margin-top:12px">${esc(h.title)}</h3><p class="muted" style="white-space:pre-wrap">${esc(h.text)}</p><small class="muted">Játékmester: ${esc(h.gm)}</small></article>`).join('')}</div>`}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-dismiss]').forEach(b=>b.onclick=()=>$('#modal').close())}
function openCharacters(){modal(`<div class="section-title"><h2>Válassz nyomozót</h2><button data-dismiss class="small" aria-label="Bezárás">✕</button></div><p class="muted">Öt alapnyomozó a prototípus kipróbálásához. A csapattársak által választott karakterek foglaltak.</p><div class="form-grid"><div class="field"><label for="search">Név keresése</label><input id="search" type="search" placeholder="Nyomozó neve…"></div><div class="field"><label for="class">Kaszt</label><select id="class"><option value="">Minden kaszt</option>${characters.map(c=>`<option>${c.class}</option>`).join('')}</select></div></div><div id="catalog" class="catalog"></div>`);const draw=()=>{$('#catalog').innerHTML=characters.filter(c=>c.name.toLowerCase().includes($('#search').value.toLowerCase())&&(!$('#class').value||c.class===$('#class').value)).map(c=>{const used=state.players.some(p=>p.char===c.id&&p.id!==state.user);return `<button class="character" data-char="${c.id}" ${used||c.id===me().char?'disabled':''}>${avatar(c)}<strong>${c.name}</strong><small>${c.class} · ${c.job}</small><span class="pill ${used?'':'gold'}">${used?'Foglalt':c.id===me().char?'Jelenlegi':'Kiválasztás'}</span></button>`}).join('')||'<p class="empty">Nincs ilyen nyomozó.</p>';document.querySelectorAll('[data-char]').forEach(b=>b.onclick=()=>{const id=b.dataset.char,c=characters.find(x=>x.id===id);modal(`<h2>${c.name} csatlakozik</h2><p>A korábbi nyomozó adatait archiváljuk az előzményekben. Az új nyomozó 0 XP-vel és traumák nélkül indul; ez a prototípus alapértéke.</p><div class="actions"><button id="confirm-character" class="primary">Karaktercsere</button><button data-dismiss>Mégse</button></div>`);$('#confirm-character').onclick=()=>{const p=me();record('Nyomozó archiválva',`${char(p).name}: ${p.earned} kapott XP, ${p.spent} elköltött XP; fizikai trauma ${p.physical}, mentális trauma ${p.mental}. Állapot: ${p.status||'–'}. Jegyzet: ${p.notes||'–'}. Pakli: ${p.deck||'–'}. Új nyomozó: ${c.name}.`);p.archive??=[];p.archive.push({...p,archive:undefined});Object.assign(p,{char:id,earned:0,spent:0,physical:0,mental:0,status:'',notes:'',deck:'',saved:false,sessionResult:null});save();$('#modal').close();render();toast('Az új nyomozó adatlapja elkészült.')}})};$('#search').oninput=draw;$('#class').onchange=draw;draw()}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>navigate('investigator',b.dataset.person));$('#user').onchange=e=>{state.user=e.target.value;detailId=null;save();render()};if($('#choose'))$('#choose').onclick=openCharacters;if($('#investigator-form'))$('#investigator-form').onsubmit=e=>{e.preventDefault();if(detailId&&detailId!==state.user)return;const f=new FormData(e.target),p=me();for(const k of ['spent','physical','mental']){const n=Number(f.get(k));if(!Number.isInteger(n)||n<0||(k==='spent'&&n>p.earned)){toast('Ellenőrizd a megadott értékeket.');return}}for(const k of ['spent','physical','mental'])p[k]=Number(f.get(k));for(const k of ['status','notes','deck'])p[k]=f.get(k).trim();record('Nyomozó adatlapja frissítve',`${char(p).name}: ${p.earned-p.spent} elkölthető XP; fizikai trauma ${p.physical}, mentális trauma ${p.mental}.`);if(save())toast('A nyomozó adatai mentve.');render()};if($('#result-form'))$('#result-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),r={xp:Number(f.get('xp')),physical:Number(f.get('physical')),mental:Number(f.get('mental')),note:f.get('note').trim()};if(![r.xp,r.physical,r.mental].every(n=>Number.isInteger(n)&&n>=0&&n<=99))return;modal(`<h2>Eredmények áttekintése</h2><p>${char(me()).name} · ${esc(state.session.title)}</p><div class="review"><p>Kapott XP: <strong>+${r.xp}</strong></p><p>Új fizikai trauma: <strong>+${r.physical}</strong></p><p>Új mentális trauma: <strong>+${r.mental}</strong></p><p>${esc(r.note)}</p></div><p class="muted">Az XP és a traumák hozzáadódnak a jelenlegi értékekhez.</p><div class="actions"><button id="confirm-result" class="primary">Eredmények mentése</button><button data-dismiss>Vissza a szerkesztéshez</button></div>`);$('#confirm-result').onclick=()=>{const p=me();if(p.saved||state.session.closed)return;p.earned+=r.xp;p.physical+=r.physical;p.mental+=r.mental;if(r.note)p.notes+=(p.notes?'\n':'')+r.note;p.saved=true;p.sessionResult=r;record(`${char(p).name} eredményei`,`${state.session.title}: +${r.xp} XP, +${r.physical} fizikai trauma, +${r.mental} mentális trauma. ${r.note}`);save();$('#modal').close();render();toast('Saját eredményeid rögzítve.')}};if($('#common-form'))$('#common-form').onsubmit=e=>{e.preventDefault();if(!gm()||state.session.closed)return;const f=new FormData(e.target);if(!f.get('resolution').trim())return;state.session.result=f.get('resolution').trim();state.session.note=f.get('note').trim();record('Közös eredmény rögzítve',state.session.result);save();render();toast('A közös eredmény mentve.')};if($('#gm'))$('#gm').onchange=e=>{const old=state.session.gm,next=e.target.value;if(!(gm()||state.user===state.owner)||state.session.closed)return;modal(`<h2>Játékmesteri szerep átadása</h2><p>${state.players.find(x=>x.id===next).name} kezeli ezután az alkalom közös dolgait. Az eddigi bejegyzések megmaradnak.</p><div class="actions"><button id="confirm-gm" class="primary">Szerep átadása</button><button data-dismiss>Mégse</button></div>`);$('#gm').value=old;$('#confirm-gm').onclick=()=>{record('Játékmester váltás',`${state.players.find(x=>x.id===old).name} → ${state.players.find(x=>x.id===next).name}`);state.session.gm=next;save();$('#modal').close();render();toast('A játékmesteri szerep átadva.')}};if($('#close-session'))$('#close-session').onclick=()=>{if(!gm()||!state.players.every(x=>x.saved)||!state.session.result||state.session.closed)return;state.session.closed=true;record(`${state.session.title} lezárva`,`${state.session.result}\n${state.session.note}`);state.notes.push({text:`${state.session.title} – ${state.session.result}\n${state.session.note}`,by:me().name,date:`${state.session.number}. alkalom`});save();render();toast('Az alkalom lezárult. Minden eredmény megmaradt.')};if($('#note-form'))$('#note-form').onsubmit=e=>{e.preventDefault();if(!gm()||state.session.closed)return;const n=new FormData(e.target).get('note').trim();if(!n)return;state.notes.push({text:n,by:me().name,date:`${state.session.number}. alkalom`});record('Közös napló bővítve',n);save();render();toast('A bejegyzés mentve.')};if($('#next'))$('#next').onclick=()=>{if(!(gm()||state.user===state.owner))return;modal(`<h2>Következő játékalkalom</h2><form id="next-form"><div class="field"><label for="next-title">Forgatókönyv neve</label><input id="next-title" name="title" required placeholder="Például: The Devourer Below"></div><div class="field"><label for="next-gm">Az alkalom játékmestere</label><select id="next-gm" name="gm">${state.players.map(p=>`<option value="${p.id}" ${p.id===state.session.gm?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="actions"><button class="primary">Alkalom indítása</button><button type="button" data-dismiss>Mégse</button></div></form>`);$('#next-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim();if(!title)return;state.session={number:state.session.number+1,title,gm:f.get('gm'),closed:false,result:'',note:''};state.players.forEach(p=>{p.saved=false;p.sessionResult=null});record('Új alkalom indult',title);save();$('#modal').close();render()}}}
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_campaign_state',title:'Kampány állapotának megtekintése',description:'A helyi prototípus aktuális játékalkalmának és nyomozóinak lekérése, módosítás nélkül.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('Nem vár paramétert.');return {session:{...state.session},players:state.players.map(p=>({name:p.name,investigator:char(p).name,xp:p.earned-p.spent,saved:p.saved}))}}})).catch(()=>{})}catch{}}
